import os

from hran_pacman.bases.wft_base import WFTDownloader  # type: ignore

from hran_admin_cli.exceptions import AdminCLIDownloaderException


class AdminCLIDownloader(WFTDownloader):
    technology = "SBTS"
    versions = []
    testpackages = []

    def __init__(self, baseline, api_key):
        super(AdminCLIDownloader, self).__init__(baseline, api_key)
        self.root_path = self._update_local_storage_path()
        self.api_key = api_key

    @property
    def downloadable_name(self):
        extension = ".zip"
        return "_".join([self.baseline, "ADMIN_CLI"]) + extension

    @property
    def package_name(self):
        return self.downloadable_name

    def download_package_from_repository(self):
        with self.temporary_container.prepare_environment():
            status = self._download_package_to_temporary_container()
            if status:
                self._copy_on_local_with_validation()
                return self.local_storage.package_path
            else:
                raise AdminCLIDownloaderException("Something went wrong, downloading status:{}".format(status))

    def _update_local_storage_path(self):
        self.local_storage.root_path = os.path.join(self.local_storage.root_path, "ADMIN_CLI")
        self.local_storage.package_path = os.path.join(
            self.local_storage.container_path, self.local_storage.package_name
        )
        return self.local_storage.root_path

    def get_site_manager(self):
        pass
